package cli

import (
	"testing"
)

func TestReleaseContextEnvStripsTagPrefixFromVersion(t *testing.T) {
	tests := []struct {
		name, nextVersion, prefix, wantVersion string
	}{
		{"default prefix", "v1.2.3", "v", "1.2.3"},
		{"monorepo prefix", "scaffolder-kubernetes-versions-0.1.0", "scaffolder-kubernetes-versions-", "0.1.0"},
		{"empty prefix", "1.2.3", "", "1.2.3"},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			env := map[string]string{}
			for _, kv := range releaseContextEnv(ReleaseSummary{NextVersion: tt.nextVersion, TagPrefix: tt.prefix}, false) {
				for i := 0; i < len(kv); i++ {
					if kv[i] == '=' {
						env[kv[:i]] = kv[i+1:]
						break
					}
				}
			}
			if env["SEMREL_VERSION"] != tt.wantVersion || env["SEMREL_NEXT_VERSION"] != tt.wantVersion {
				t.Errorf("version = %q / %q, want %q", env["SEMREL_VERSION"], env["SEMREL_NEXT_VERSION"], tt.wantVersion)
			}
			if env["SEMREL_TAG_NAME"] != tt.nextVersion {
				t.Errorf("SEMREL_TAG_NAME = %q, want %q", env["SEMREL_TAG_NAME"], tt.nextVersion)
			}
		})
	}
}
